package kome.common.data;
import kome.common.KOMEReflection;import kome.common.KOMEAddon;import lotr.common.LOTRLevelData;import lotr.common.entity.npc.LOTREntityNPC;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;
/** Server-only Courier validation and item identity checks. */
public final class KOMECourierService {
 private KOMECourierService(){} public static ItemStack message(KOMESerfCourierAssignment a,EntityPlayerMP p,KOMEProgressionNpcRef master){ItemStack s=new ItemStack(a.kind==KOMESerfCourierAssignment.Kind.PARCEL?KOMEAddon.sealedParcel:KOMEAddon.sealedMessage);NBTTagCompound t=new NBTTagCompound();t.setString("CourierAssignmentId",a.token);t.setString("PlayerUUID",KOMEReflection.getEntityUUID(p).toString());t.setString("MasterUUID",master.entityUuid);t.setString("MasterName",master.displayName);t.setString("CourierKind",a.kind.key);t.setString("Cargo",a.cargo);s.setTagCompound(t);return s;}
 public static boolean matching(ItemStack s,KOMESerfCourierAssignment a,EntityPlayerMP p,KOMEProgressionNpcRef master){if(s==null||a==null||s.getItem()!=(a.kind==KOMESerfCourierAssignment.Kind.PARCEL?KOMEAddon.sealedParcel:KOMEAddon.sealedMessage)||!s.hasTagCompound())return false;NBTTagCompound t=s.getTagCompound();return a.valid()&&a.kind.key.equals(t.getString("CourierKind"))&&a.token.equals(t.getString("CourierAssignmentId"))&&KOMEReflection.getEntityUUID(p).toString().equals(t.getString("PlayerUUID"))&&master.entityUuid.equals(t.getString("MasterUUID"));}
 public static boolean hasMessage(EntityPlayerMP p,KOMESerfCourierAssignment a,KOMEProgressionNpcRef m){for(ItemStack s:p.inventory.mainInventory)if(matching(s,a,p,m))return true;return false;}
 public static boolean removeMessage(EntityPlayerMP p,KOMESerfCourierAssignment a,KOMEProgressionNpcRef m){for(int i=0;i<p.inventory.mainInventory.length;i++)if(matching(p.inventory.mainInventory[i],a,p,m)){p.inventory.mainInventory[i]=null;return true;}return false;}
 public static boolean validRecipient(EntityPlayerMP p,LOTREntityNPC n,KOMESerfCourierAssignment a,KOMEProgressionNpcRef master){return n!=null&&n.isEntityAlive()&&!n.isChild()&&KOMEProgressionNpcRankService.isValidFactionNpc(n)&&n.hiredNPCInfo!=null&&!n.hiredNPCInfo.isActive&&!master.hasSameIdentity(KOMEProgressionNpcRankService.referenceOf(n))&&a.stage==KOMESerfCourierAssignment.Stage.OUTBOUND&&a.masterFactionKey.equals(n.getFaction().codeName())&&a.masterFactionKey.equals(LOTRLevelData.getData(p).getPledgeFaction().codeName())&&a.farEnough(n.worldObj.provider.dimensionId,n.posX,n.posZ)&&p.getDistanceSqToEntity(n)<=64.0D;}
}
